//! Render-fidelity comparison against C Graphviz 16.1.0 (`gv-diff render`).
//!
//! The corpus under `tests/golden/render/` (see `scripts/gen-render-golden.sh`) holds C
//! layouts (`laid/STEM.dot`) and C's renderings of them in no-layout mode
//! (`neato -n2 -TFORMAT`). The port renders the same inputs with `-Kneato -n2`, so any
//! difference comes from the renderers (or from node sizing, which `-n2` recomputes).
//!
//! A file counts as identical when the bytes match, except that the SVG generator comment
//! (`<!-- Generated by ... -->`), which names the program, is ignored. For other files the
//! report gives the number of lines present on one side only (a multiset difference over
//! lines, so it is cheap on large outputs).

use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

/// Output formats in the corpus: directory name and file extension.
pub const FORMATS: &[&str] = &["svg", "json", "json0", "xdot", "dot", "plain", "plain-ext"];

/// References that C does not reproduce from run to run, skipped. In `-Tplain`, a label
/// whose converted text (`htmlEntityUTF8`, e.g. `&infin;`, or `latin1ToUTF8`) is not
/// already an interned string and needs no quoting is printed after `canon` in
/// `lib/common/output.c` has freed it (`agstrcanon` returns its argument unquoted, then
/// `agstrfree` releases it), so the label field is whatever the freed memory holds.
pub const UNSTABLE: &[(&str, &str)] = &[
    ("plain", "gallery__index_7_fe2a40"),
    ("plain", "gv16_graphs_Symbol_af1a2d"),
    ("plain", "gv16_graphs_b34_ca01c7"),
    ("plain", "gv16_graphs_b56_36f937"),
    ("plain", "charset_Latin1"),
    ("plain", "charset_b34"),
    ("plain", "charset_b56"),
    ("plain", "charset_b60"),
    ("plain", "charset_latin1_html"),
    ("plain", "charset_latin1_mixed"),
    ("plain-ext", "gallery__index_7_fe2a40"),
    ("plain-ext", "gv16_graphs_Symbol_af1a2d"),
    ("plain-ext", "gv16_graphs_b34_ca01c7"),
    ("plain-ext", "gv16_graphs_b56_36f937"),
    ("plain-ext", "charset_Latin1"),
    ("plain-ext", "charset_b34"),
    ("plain-ext", "charset_b56"),
    ("plain-ext", "charset_b60"),
    ("plain-ext", "charset_latin1_html"),
    ("plain-ext", "charset_latin1_mixed"),
];

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct RenderReport {
    pub identical: bool,
    /// Lines present in one output only.
    pub diff_lines: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

/// Per format, per file stem.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct RenderBaseline {
    pub formats: BTreeMap<String, BTreeMap<String, RenderReport>>,
}

impl RenderBaseline {
    pub fn identical(&self, fmt: &str) -> usize {
        self.formats
            .get(fmt)
            .map_or(0, |m| m.values().filter(|r| r.identical).count())
    }
    pub fn diff_lines(&self, fmt: &str) -> usize {
        self.formats
            .get(fmt)
            .map_or(0, |m| m.values().map(|r| r.diff_lines).sum())
    }
}

fn is_generator_comment(line: &str) -> bool {
    line.starts_with("<!-- Generated by ")
}

/// Compares two outputs; `svg` enables the generator-comment exception.
pub fn compare_output(reference: &str, actual: &str, svg: bool) -> RenderReport {
    let keep = |l: &&str| !(svg && is_generator_comment(l));
    let a: Vec<&str> = reference.split_inclusive('\n').filter(keep).collect();
    let b: Vec<&str> = actual.split_inclusive('\n').filter(keep).collect();
    if a == b {
        return RenderReport {
            identical: true,
            ..RenderReport::default()
        };
    }
    let mut counts: HashMap<&str, i64> = HashMap::new();
    for l in &a {
        *counts.entry(l.trim_end_matches(['\n', '\r'])).or_insert(0) += 1;
    }
    for l in &b {
        *counts.entry(l.trim_end_matches(['\n', '\r'])).or_insert(0) -= 1;
    }
    let diff: i64 = counts.values().map(|v| v.abs()).sum();
    RenderReport {
        identical: false,
        // Same lines in another order (or a trailing newline) still count as a difference.
        diff_lines: (diff as usize).max(1),
        error: None,
    }
}

/// Renders `laid` with the port in `-n2` mode, catching panics.
pub fn render_port(laid: &str, format: &str) -> Result<String, String> {
    let src = laid.to_string();
    let fmt = format.to_string();
    let res = std::panic::catch_unwind(move || {
        gv_engine::render_dot_all_with_options(
            &src,
            "neato",
            &fmt,
            &gv_engine::GlobalAttrs::default(),
            gv_engine::LayoutOptions { nop: 2 },
        )
    });
    match res {
        Ok(Ok(outs)) => Ok(outs.concat()),
        Ok(Err(e)) => Err(format!("error: {e}")),
        Err(p) => Err(format!(
            "panic: {}",
            p.downcast_ref::<String>()
                .map(String::as_str)
                .or_else(|| p.downcast_ref::<&str>().copied())
                .unwrap_or("?")
        )),
    }
}

/// Runs every corpus file for `formats`, in parallel.
pub fn run_corpus(root: &Path, formats: &[&str], filter: Option<&str>) -> RenderBaseline {
    let laid_dir = root.join("laid");
    let mut stems: Vec<String> = std::fs::read_dir(&laid_dir)
        .map(|rd| {
            rd.flatten()
                .filter_map(|e| {
                    let p = e.path();
                    (p.extension().is_some_and(|x| x == "dot"))
                        .then(|| p.file_stem().unwrap().to_string_lossy().to_string())
                })
                .collect()
        })
        .unwrap_or_default();
    stems.sort();
    if let Some(f) = filter {
        stems.retain(|s| s.contains(f));
    }
    let mut jobs: Vec<(String, String, PathBuf)> = Vec::new();
    for fmt in formats {
        for stem in &stems {
            let reference = root.join(fmt).join(format!("{stem}.{fmt}"));
            if reference.exists() && !UNSTABLE.contains(&(fmt, stem.as_str())) {
                jobs.push((fmt.to_string(), stem.clone(), reference));
            }
        }
    }
    std::panic::set_hook(Box::new(|_| {}));
    let out: Mutex<RenderBaseline> = Mutex::new(RenderBaseline::default());
    let next = Mutex::new(0usize);
    let threads = std::thread::available_parallelism().map_or(4, |n| n.get());
    std::thread::scope(|s| {
        for _ in 0..threads {
            s.spawn(|| {
                loop {
                    let i = {
                        let mut n = next.lock().unwrap();
                        let i = *n;
                        *n += 1;
                        i
                    };
                    let Some((fmt, stem, reference)) = jobs.get(i) else {
                        break;
                    };
                    let laid = std::fs::read(laid_dir.join(format!("{stem}.dot")))
                        .map(gv_core::charset::decode)
                        .unwrap_or_default();
                    let refs = std::fs::read(reference).unwrap_or_default();
                    let refs = gv_core::charset::decode(refs);
                    let report = match render_port(&laid, fmt) {
                        Ok(actual) => compare_output(&refs, &actual, fmt == "svg"),
                        Err(e) => RenderReport {
                            identical: false,
                            diff_lines: refs.lines().count(),
                            error: Some(e),
                        },
                    };
                    out.lock()
                        .unwrap()
                        .formats
                        .entry(fmt.clone())
                        .or_default()
                        .insert(stem.clone(), report);
                }
            });
        }
    });
    let _ = std::panic::take_hook();
    out.into_inner().unwrap()
}

pub fn print_summary(cur: &RenderBaseline, base: Option<&RenderBaseline>) {
    println!(
        "{:<10} {:>9} {:>7} {:>11} {:>7}",
        "format", "identical", "files", "diff lines", "errors"
    );
    for (fmt, files) in &cur.formats {
        let errors = files.values().filter(|r| r.error.is_some()).count();
        let mut line = format!(
            "{:<10} {:>9} {:>7} {:>11} {:>7}",
            fmt,
            cur.identical(fmt),
            files.len(),
            cur.diff_lines(fmt),
            errors
        );
        if let Some(b) = base {
            line.push_str(&format!(
                "   (baseline {} identical, {} diff lines)",
                b.identical(fmt),
                b.diff_lines(fmt)
            ));
        }
        println!("{line}");
    }
}

/// Fails when a format loses identical files (any previously identical file must stay so)
/// or its total line difference grows.
pub fn check(base: &RenderBaseline, cur: &RenderBaseline) -> bool {
    let mut ok = true;
    for (fmt, files) in &cur.formats {
        let Some(old) = base.formats.get(fmt) else {
            continue;
        };
        let mut broken = Vec::new();
        let (mut old_lines, mut new_lines) = (0usize, 0usize);
        for (stem, r) in files {
            let Some(o) = old.get(stem) else { continue };
            old_lines += o.diff_lines;
            new_lines += r.diff_lines;
            if o.identical && !r.identical {
                broken.push(stem.clone());
            }
        }
        if !broken.is_empty() {
            ok = false;
            println!(
                "FAIL {fmt}: {} files no longer identical: {}",
                broken.len(),
                broken.join(", ")
            );
        }
        if new_lines > old_lines {
            ok = false;
            println!("FAIL {fmt}: diff lines grew {old_lines} -> {new_lines}");
        }
    }
    ok
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compare_ignores_svg_generator_line_only() {
        let a = "<?xml?>\n<!-- Generated by graphviz version 16.1.0\n -->\n<svg/>\n";
        let b = "<?xml?>\n<!-- Generated by graphvis-rs\n -->\n<svg/>\n";
        assert!(compare_output(a, b, true).identical);
        assert!(!compare_output(a, b, false).identical);
        let r = compare_output("a\nb\nc\n", "a\nc\nd\n", false);
        assert_eq!(r.diff_lines, 2);
        let r = compare_output("a\nb\n", "b\na\n", false);
        assert!(!r.identical && r.diff_lines == 1);
    }
}
